def main():
    data = ROADMAP.read_bytes()
    if b"\r\n" in data:
        raise SystemExit("REFUSED: the roadmap is LF and CRLF was found; nothing written")
    text = data.decode("utf-8")
    if "\n**260. " in text and all(text.count(new + "\n**%s. " % n) == 1 for n, _, new in ENTRIES):
        print("already applied")
        return 0
    if "\n**260. " in text:
        raise SystemExit("REFUSED: an item 260 exists and the statuses are not this patch's; nothing written")
    for n, old, _ in ENTRIES:
        if text.count(old) != 1 or text.count(old + "\n**%s. " % n) != 1:
            raise SystemExit("REFUSED: item %s's status block is not there once, above its heading; nothing written" % n)
    for n, old, new in ENTRIES:
        text = text.replace(old, new)
    text = text + ("" if text.endswith("\n") else "\n") + "\n" + NEW_ITEM
    out = text.encode("utf-8")
    ROADMAP.write_bytes(out)
    print("%d statuses updated, item 260 appended: %d -> %d bytes" % (len(ENTRIES), len(data), len(out)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
